225	class _Text(HTMLParser):
226	    def __init__(self):
227	        super().__init__()
228	        self.parts, self.skip = [], 0
229	
230	    def handle_starttag(self, tag, attrs):
231	        if tag in ("script", "style"):
232	            self.skip += 1
233	        elif tag in ("p", "div", "tr", "br", "li", "h1", "h2", "h3", "table"):
234	            self.parts.append("\n")
235	        elif tag in ("td", "th"):
236	            self.parts.append(" | ")
237	
238	    def handle_endtag(self, tag):
239	        if tag in ("script", "style") and self.skip:
240	            self.skip -= 1
241	
242	    def handle_data(self, data):
243	        if not self.skip:
244	            self.parts.append(data)
245	
246	
247	def clean_text(text: str) -> str:
248	    text = re.sub(r"[​-‏⁠-⁤﻿­͏؜᠎]", "", text)
249	    return re.sub(r"\n\s*\n+", "\n", re.sub(r"[ \t ]+", " ", text)).strip()
250	
251	
252	def document_text(data: bytes, content_type: str, name: str, depth: int = 0) -> str:
253	    """The text of a fetched file: archives are opened, markup is stripped, PDFs are read when pypdf is installed."""
254	    kind = (content_type or "").lower()
255	    lower = name.lower()
256	    if data[:4] == b"PK\x03\x04" or "zip" in kind or lower.endswith(".zip"):
257	        try:
258	            archive = zipfile.ZipFile(io.BytesIO(data))
259	        except zipfile.BadZipFile:
260	            return "(unreadable archive)"
261	        parts = [f"ARCHIVE {name} with files: " + ", ".join(info.filename for info in archive.infolist())]
262	        for info in archive.infolist()[:40]:
263	            if info.is_dir() or depth > 2:
264	                continue
265	            parts.append(f"=== FILE {info.filename} ===\n" + document_text(archive.read(info), "", info.filename, depth + 1))
266	        return "\n".join(parts)
267	    if data[:5] == b"%PDF-" or "pdf" in kind:
268	        try:
269	            from pypdf import PdfReader
270	            return clean_text("\n".join(page.extract_text() or "" for page in PdfReader(io.BytesIO(data)).pages))
271	        except Exception as error:  # noqa: BLE001
272	            return f"(PDF could not be read: {error})"
273	    text = data.decode("utf-8", errors="replace")
274	    if "html" in kind or "xml" in kind or re.search(r"<(html|body|table|div|p|w:document|worksheet)\b", text[:4000], re.I):
275	        parser = _Text()
276	        parser.feed(text)
277	        text = "".join(parser.parts)
278	    return clean_text(text)
