281	class Tab:
282	    """One browser tab on one website, driven by one agent."""
283	
284	    def __init__(self, page, site: dict):
285	        self.page = page
286	        self.site_id = site.get("siteId", "")
287	        self.base_url = site["url"].rstrip("/")
288	        self.credentials = site.get("credentials") or {}
289	        self.frames: list[tuple[int, int, object]] = []  # id range -> frame
290	        self.document = ""  # what `keep` files: the page as last read, a collected listing or a fetched file
291	        self.document_source = ""
292	        self.events: list[str] = []
293	        self.bad_status = 0
294	        page.on("dialog", lambda dialog: asyncio.ensure_future(self._on_dialog(dialog)))
295	        page.on("response", self._on_response)
296	
297	    async def _on_dialog(self, dialog):
298	        self.events.append(f'the browser asked "{dialog.message}" ({dialog.type}); it was accepted')
299	        try:
300	            await dialog.accept()
301	        except Exception:  # noqa: BLE001
302	            pass
303	
304	    def _on_response(self, response):
305	        try:
306	            if response.request.is_navigation_request() and response.frame == self.page.main_frame:
307	                self.bad_status = response.status if response.status >= 500 else 0
308	        except Exception:  # noqa: BLE001
309	            pass
310	
311	    async def settle(self):
312	        for state, timeout in (("domcontentloaded", 15000), ("networkidle", 2500)):
313	            try:
314	                await self.page.wait_for_load_state(state, timeout=timeout)
315	            except Exception:  # noqa: BLE001
316	                pass
317	        for _ in range(3):  # a server error page: retry the same address, as a person would press reload
318	            if not self.bad_status:
319	                break
320	            self.events.append(f"the server answered HTTP {self.bad_status}; reloaded")
321	            await asyncio.sleep(0.4)
322	            try:
323	                await self.page.reload(wait_until="domcontentloaded", timeout=15000)
324	            except Exception:  # noqa: BLE001
325	                break
326	
327	    async def _frame_text(self, frame, start: int, depth: int) -> tuple[str, int]:
328	        try:
329	            prepared = await frame.evaluate(PREPARE_JS)
330	            if prepared["opened"]:
331	                await asyncio.sleep(0.15)  # lazy content of the sections just opened
332	                try:
333	                    await self.page.wait_for_load_state("networkidle", timeout=2000)
334	                except Exception:  # noqa: BLE001
335	                    pass
336	            for name in prepared["closed"]:
337	                self.events.append(f'closed the popup "{name}"')
338	            shot = await frame.evaluate(SNAPSHOT_JS, start)
339	        except Exception as error:  # noqa: BLE001
340	            return f"(this document could not be read: {str(error)[:120]})", start
341	        self.frames.append((start, shot["next"], frame))
342	        text, following = shot["text"], shot["next"]
343	        for marker in re.findall(r"⟦FRAME:(\d+)⟧", text):
344	            inner = "(embedded document not loaded)"
345	            if depth < 4:
346	                try:
347	                    handle = await frame.query_selector(f'[data-aid="{marker}"]')
348	                    child = await handle.content_frame() if handle else None
349	                    if child:
350	                        try:
351	                            await child.wait_for_load_state("domcontentloaded", timeout=4000)
352	                        except Exception:  # noqa: BLE001
353	                            pass
354	                        inner, following = await self._frame_text(child, following, depth + 1)
355	                except Exception as error:  # noqa: BLE001
356	                    inner = f"(embedded document could not be read: {str(error)[:120]})"
357	            block = "┌── embedded document: " if inner.strip() else "┌── embedded document (empty): "
358	            text = text.replace(f"⟦FRAME:{marker}⟧", block, 1).replace(
359	                block, block, 1)
360	            # the marker line carries the frame's title; append the frame's content under it
361	            lines = text.split("\n")
362	            for index, line in enumerate(lines):
363	                if line.startswith(block) and not line.endswith("⁣"):
364	                    lines[index] = line + "⁣"
365	                    lines.insert(index + 1, "\n".join("│ " + row for row in inner.split("\n")) + "\n└── end of embedded document")
366	                    break
367	            text = "\n".join(lines)
368	        return text.replace("⁣", ""), following
369	
370	    async def read(self) -> str:
371	        """The current page as text, with fresh element ids."""
372	        await self.settle()
373	        self.frames = []
374	        text, _ = await self._frame_text(self.page.main_frame, 1, 0)
375	        try:
376	            title = await self.page.title()
377	        except Exception:  # noqa: BLE001
378	            title = ""
379	        self.document = clean_text(text)
380	        self.document_source = self.page.url
381	        return f"url: {self.page.url}\ntitle: {clean_text(title)}\n{self.document}"
382	
383	    async def observe(self) -> str:
384	        text = await self.read()
385	        if len(text) > MAX_OBSERVATION:
386	            text = text[:MAX_OBSERVATION] + f"\n… (page text cut here; {len(text) - MAX_OBSERVATION} more characters. `keep` files the whole page.)"
387	        return text
388	
389	    def take_events(self) -> list[str]:
390	        events, self.events = self.events, []
391	        return events
392	
393	    def _locator(self, aid):
394	        try:
395	            number = int(aid)
396	        except (TypeError, ValueError):
397	            return None
398	        for start, end, frame in self.frames:
399	            if start <= number < end:
400	                return frame.locator(f'[data-aid="{number}"]')
401	        return None
402	
403	    async def _describe(self, locator) -> dict:
404	        return await locator.evaluate(
405	            """el => ({tag: el.tagName, type: (el.getAttribute('type') || '').toLowerCase(), href: el.href || '',
406	                      disabled: el.disabled === true || !!el.closest('fieldset[disabled],[inert]'),
407	                      name: (el.innerText || el.value || el.getAttribute('aria-label') || '').replace(/\\s+/g, ' ').trim().slice(0, 80)})""")
408	
409	    async def click(self, aid) -> str:
410	        locator = self._locator(aid)
411	        if locator is None or await locator.count() == 0:
412	            return f"there is no element [{aid}] on the page any more; read the current page"
413	        info = await self._describe(locator)
414	        if info["disabled"]:
415	            return f"[{aid}] is disabled (inside a locked or inert area?); nothing happened"
416	        before = self.page.url
417	        try:
418	            await locator.click(timeout=2500)
419	        except Exception:  # noqa: BLE001  hidden in a collapsed menu, or covered: activate it directly
420	            try:
421	                await locator.evaluate("el => el.click()")
422	            except Exception as error:  # noqa: BLE001
423	                return f"could not click [{aid}]: {str(error)[:150]}"
424	        await self.settle()
425	        moved = self.page.url != before
426	        return f'clicked [{aid}] "{info["name"]}"' + (f"; now at {self.page.url}" if moved else "")
427	
428	    async def fill(self, aid, text: str, enter: bool = False) -> str:
429	        locator = self._locator(aid)
430	        if locator is None or await locator.count() == 0:
431	            return f"there is no element [{aid}] on the page any more"
432	        try:
433	            await locator.fill(str(text), timeout=2500)
434	        except Exception as error:  # noqa: BLE001
435	            return f"could not fill [{aid}]: {str(error)[:150]}"
436	        if enter:
437	            await locator.press("Enter")
438	            await self.settle()
439	        return f"filled [{aid}]" + (" and pressed Enter" if enter else "")
440	
441	    async def select(self, aid, value: str) -> str:
442	        locator = self._locator(aid)
443	        if locator is None or await locator.count() == 0:
444	            return f"there is no element [{aid}] on the page any more"
445	        wanted = str(value)
446	        for attempt in ({"value": wanted}, {"label": wanted}):
447	            try:
448	                await locator.select_option(timeout=2000, **attempt)
449	                await self.settle()
450	                return f'selected "{wanted}" in [{aid}]'
451	            except Exception:  # noqa: BLE001
452	                continue
453	        options = await locator.evaluate("el => [...(el.options || [])].map(o => o.value + '=' + o.textContent.trim())")
454	        loose = [o.split("=", 1)[0] for o in options if wanted.lower() in o.lower()]
455	        if len(loose) == 1:
456	            await locator.select_option(value=loose[0])
457	            await self.settle()
458	            return f'selected "{loose[0]}" in [{aid}]'
459	        return f'[{aid}] has no option "{wanted}"; options: {"; ".join(options)[:600]}'
460	
461	    async def set(self, aid, value) -> str:
462	        locator = self._locator(aid)
463	        if locator is None or await locator.count() == 0:
464	            return f"there is no element [{aid}] on the page any more"
465	        info = await self._describe(locator)
466	        if info["disabled"]:
467	            return f"[{aid}] is disabled; nothing happened"
468	        try:
469	            if info["type"] in ("checkbox", "radio"):
470	                await locator.set_checked(bool(value), timeout=2500, force=True)
471	            else:  # a slider or another input whose value is set in one go
472	                await locator.evaluate(
473	                    """(el, v) => { const proto = Object.getPrototypeOf(el); const d = Object.getOwnPropertyDescriptor(proto, 'value');
474	                                   d && d.set ? d.set.call(el, String(v)) : el.value = String(v);
475	                                   el.dispatchEvent(new Event('input', {bubbles: true})); el.dispatchEvent(new Event('change', {bubbles: true})); }""",
476	                    value)
477	        except Exception as error:  # noqa: BLE001
478	            return f"could not set [{aid}]: {str(error)[:150]}"
479	        await self.settle()
480	        return f"set [{aid}] to {value}"
481	
482	    def _on_site(self, url: str) -> bool:
483	        return urlparse(url).netloc == urlparse(self.base_url).netloc
484	
485	    async def goto(self, url: str) -> str:
486	        target = urljoin(self.page.url if self._on_site(self.page.url) else self.base_url + "/", str(url).strip())
487	        if not self._on_site(target):
488	            return f"{target} is not on this website; you only work on {self.base_url}"
489	        try:
490	            await self.page.goto(target, wait_until="domcontentloaded", timeout=20000)
491	        except Exception as error:  # noqa: BLE001
492	            return f"could not open {target}: {str(error)[:150]}"
493	        await self.settle()
494	        return f"opened {self.page.url}"
495	
496	    async def back(self) -> str:
497	        try:
498	            await self.page.go_back(wait_until="domcontentloaded", timeout=15000)
499	        except Exception as error:  # noqa: BLE001
500	            return f"could not go back: {str(error)[:120]}"
501	        await self.settle()
502	        return f"went back to {self.page.url}"
503	
504	    async def reload(self) -> str:
505	        try:
506	            await self.page.reload(wait_until="domcontentloaded", timeout=15000)
507	        except Exception as error:  # noqa: BLE001
508	            return f"could not reload: {str(error)[:120]}"
509	        await self.settle()
510	        return "reloaded the page"
511	
512	    async def login(self) -> str:
513	        if not self.credentials.get("password"):
514	            return "there are no credentials for this website"
515	        outcome = "no password field on this page"
516	        for frame in self.page.frames:
517	            try:
518	                outcome = await frame.evaluate(LOGIN_JS, [self.credentials.get("username", ""), self.credentials["password"]])
519	            except Exception:  # noqa: BLE001
520	                continue
521	            if outcome == "ok":
522	                await frame.locator("[data-login-password]").first.press("Enter")
523	                await self.settle()
524	                return f"entered the credentials and submitted the login form; now at {self.page.url}"
525	        return outcome
526	
527	    async def collect(self, aid, max_pages: int = 10) -> str:
528	        """Follow the paging control the model chose until it is gone, and return every page as one document."""
529	        locator = self._locator(aid)
530	        if locator is None or await locator.count() == 0:
531	            return f"there is no element [{aid}] on the page any more"
532	        info = await self._describe(locator)
533	        if not info["name"]:
534	            return f"[{aid}] has no label to follow from page to page"
535	        first = self.document
536	        pages, seen = [first], {first}
537	        for _ in range(max(1, min(int(max_pages or 10), 30)) - 1):
538	            control = None
539	            for _, _, frame in self.frames:
540	                candidates = frame.locator("a[href], button, [role=button], [role=link]")
541	                for index in range(min(await candidates.count(), 200)):
542	                    candidate = candidates.nth(index)
543	                    try:
544	                        label = clean_text(await candidate.evaluate("el => el.innerText || el.value || el.getAttribute('aria-label') || ''"))
545	                        if label == info["name"] and (await candidate.evaluate("el => el.tagName")) == info["tag"] \
546	                                and not await candidate.evaluate("el => el.disabled === true"):
547	                            control = candidate
548	                            break
549	                    except Exception:  # noqa: BLE001
550	                        continue
551	                if control:
552	                    break
553	            if control is None:
554	                break
555	            try:
556	                await control.click(timeout=2500)
557	            except Exception:  # noqa: BLE001
558	                try:
559	                    await control.evaluate("el => el.click()")
560	                except Exception:  # noqa: BLE001
561	                    break
562	            await self.read()
563	            if self.document in seen:
564	                break
565	            seen.add(self.document)
566	            pages.append(self.document)
567	        grows = len(pages) > 1 and all(later.startswith(pages[0][:200]) and len(later) >= len(earlier)
568	                                       for earlier, later in zip(pages, pages[1:])) and info["tag"] != "A"
569	        if grows:  # a "load more" control: the last page holds every row
570	            self.document = pages[-1]
571	            return f'followed "{info["name"]}" {len(pages) - 1} time(s); the list is now complete on the page'
572	        self.document = "\n".join(f"===== page {number} of the collected list =====\n{page}" for number, page in enumerate(pages, 1))
573	        return (f'followed "{info["name"]}" through {len(pages)} page(s). COLLECTED DOCUMENT (file it with keep if it '
574	                f"is relevant; the element ids below are only valid for the last page):\n{self.document[:MAX_OBSERVATION * 2]}")
575	
576	    async def fetch(self, aid) -> str:
577	        """Download what the chosen link points to and read it as a document."""
578	        locator = self._locator(aid)
579	        if locator is None or await locator.count() == 0:
580	            return f"there is no element [{aid}] on the page any more"
581	        target = await locator.evaluate("el => el.href || el.src || el.getAttribute('data-url') || el.getAttribute('formaction') || ''")
582	        if not target:
583	            return f"[{aid}] has no address to download"
584	        target = urljoin(self.page.url, target)
585	        if not self._on_site(target):
586	            return f"{target} is not on this website"
587	        try:
588	            response = await self.page.context.request.get(target, timeout=20000)
589	            data = await response.body()
590	        except Exception as error:  # noqa: BLE001
591	            return f"could not download {target}: {str(error)[:150]}"
592	        name = urlparse(target).path.rsplit("/", 1)[-1] or "download"
593	        disposition = response.headers.get("content-disposition", "")
594	        named = re.search(r'filename\*?=(?:UTF-8\'\')?"?([^";]+)', disposition)
595	        if named:
596	            name = named.group(1)
597	        self.document = document_text(data, response.headers.get("content-type", ""), name)
598	        self.document_source = target
599	        return (f"downloaded {name} (HTTP {response.status}, {len(data)} bytes). DOCUMENT (file it with keep if it is "
600	                f"relevant):\n{self.document[:MAX_OBSERVATION * 2]}")
